head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.fn_openPopup = function(a) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var rowJSON = {
        "poupObjectNm": "popup1"
    };
    //popup에 넘길 data객체. 
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array" 
        data: rowJSON, // 전달 데이터 객체. 
        name: "paramTest" // 변수명. popup에서 $w.getParameter( "paramTest" )로 깨내올 수 있다. 
    };
    var options = {
        id: "popup1",
        type: "wframePopup", //browserPopup //wframePopup
        width: 300 + "px",
        height: 300 + "px",
        top: 100 + "px",
        left: 100 + "px",
        modal: true,
        useModalStack: true,
        onlyParam: true,
        style: "",
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: false,
        title: false,
        useMaximize: true,
        dataObject: dataObj
    };
    $p.openPopup("gridView_excelUpload_wframe_WESD-341_(WSQ-4508)_popup.xml", options);
};
scwin.trigger3_onclick = function(e) {
    scwin.fn_openPopup("bbb");
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('popup1_wframe_trigger16').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#_modal').hasClass('w2modal_popup')", "true");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload = function() {
    if (typeof scwin.onpageload === "function") {
        //scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
